def validate_qos_config(config):
    if not isinstance(config, dict) or frozenset(config) != QOS_CONFIG_KEYS:
        raise InvalidInput("bad config")
    (
        bridges,
        links,
        delay,
        bridge,
        ports,
        age,
        storm,
        lags,
        mirror,
        acl,
    ) = validate_acl_config(
        {
            "bridges": config["bridges"],
            "links": config["links"],
            "delay": config["delay"],
            "bridge": config["bridge"],
            "ports": config["ports"],
            "age": config["age"],
            "storm": config["storm"],
            "lags": config["lags"],
            "mirror": config["mirror"],
            "acl": config["acl"],
        }
    )
    qos = config["qos"]
    if not isinstance(qos, dict) or frozenset(qos) != QOS_KEYS:
        raise InvalidInput("bad qos")
    mapping = qos["map"]
    cap = qos["cap"]
    mode = qos["mode"]
    weights = qos["weights"]
    drop = qos["drop"]
    if (
        not isinstance(mapping, list)
        or len(mapping) != 8
        or not all(_is_int(q) and 0 <= q <= 3 for q in mapping)
    ):
        raise InvalidInput("bad qos map")
    if not _is_int(cap) or cap <= 0:
        raise InvalidInput("bad qos cap")
    if mode not in QOS_SCHED_MODES:
        raise InvalidInput("bad qos mode")
    if (
        not isinstance(weights, list)
        or len(weights) != 4
        or not all(_is_int(w) and w > 0 for w in weights)
    ):
        raise InvalidInput("bad qos weights")
    if drop not in QOS_DROP_MODES:
        raise InvalidInput("bad qos drop")
    parsed = {
        "map": list(mapping),
        "cap": cap,
        "mode": mode,
        "weights": list(weights),
        "drop": drop,
    }
    return (
        bridges, links, delay, bridge, ports, age, storm, lags, mirror, acl,
        parsed,
    )


def _qos_quotas(qos):
    """weighted 丢弃下各队列上取整配额 ceil(cap*w_i/sum(w))。"""
    weights = qos["weights"]
    total = sum(weights)
    cap = qos["cap"]
    return [-(-(cap * w) // total) for w in weights]


def _qos_queues_fit(counts, qos):
    """热加载取新配置后出口四队列是否仍合法。

    tail：四队列总数不得超过 cap；weighted：队列 i 不得超过
    ceil(cap*weights[i]/sum(weights))。
    """
    if qos["drop"] == "tail":
        return sum(counts) <= qos["cap"]
    quotas = _qos_quotas(qos)
    return all(counts[i] <= quotas[i] for i in range(4))


class _TsQueue:
    """单调时间戳队列：逻辑视图为 items[head:]，支持按窗口 O(log n) 计数。

    热加载缩短当前 storm window 时，已落在新窗口外但未过历代最大窗口的
    记录仍须保留（回滚到长窗口后恢复影响），故不能像旧实现那样仅按当前
    窗口左修剪后用 len() 判定。用带 head 的有序表：popleft 懒推进 head，
    积累到一半即压缩，总内存 O(事件数)，判定 O(log n)。
    """

    __slots__ = ("items", "head")

    def __init__(self):
        self.items = []
        self.head = 0

    def __len__(self):
        return len(self.items) - self.head

    def __bool__(self):
        return self.head < len(self.items)

    def __getitem__(self, index):
        return self.items[self.head + index]

    def append(self, ts):
        self.items.append(ts)

    def popleft(self):
        ts = self.items[self.head]
        self.head += 1
        if self.head >= 64 and self.head * 2 >= len(self.items):
            del self.items[:self.head]
            self.head = 0
        return ts

    def window_count(self, t, window):
        """当前 window 内（t - ts < window）记录数。"""
        return len(self.items) - bisect.bisect_right(
            self.items, t - window, self.head
        )


def _storm_prune(queue, t, retain_window):
    """弹出超出保留窗口的风暴/MAC 迁移时间记录（左闭边界同判定规则）。"""
    while queue and t - queue[0] >= retain_window:
        queue.popleft()


def _storm_window_count(queue, t, window):
    """当前 window 内（t - ts < window）的记录数；队列按时间升序。"""
    return queue.window_count(t, window)


def validate_security_config(config):
    if not isinstance(config, dict) or frozenset(config) != SECURITY_CONFIG_KEYS:
        raise InvalidInput("bad config")
    (
        bridges,
        links,
        delay,
        bridge,
        ports,
        age,
        storm,
        lags,
        mirror,
        acl,
        qos,
    ) = validate_qos_config(
        {
            "bridges": config["bridges"],
            "links": config["links"],
            "delay": config["delay"],
            "bridge": config["bridge"],
            "ports": config["ports"],
            "age": config["age"],
            "storm": config["storm"],
            "lags": config["lags"],
            "mirror": config["mirror"],
            "acl": config["acl"],
            "qos": config["qos"],
        }
    )
    security = config["security"]
    if not isinstance(security, list):
        raise InvalidInput("bad security")
    names = {port["name"] for port in ports}
    seen = set()
    statics = set()  # 全局互异的 (vlan, mac)
    parsed = []
    for entry in security:
        if not isinstance(entry, dict) or frozenset(entry) != SECURITY_KEYS:
            raise InvalidInput("bad security entry")
        port = entry["port"]
        limit = entry["limit"]
        action = entry["action"]
        static = entry["static"]
        if not isinstance(port, str) or port not in names or port in seen:
            raise InvalidInput("bad security port")
        seen.add(port)
        if not _is_int(limit) or limit < 0:
            raise InvalidInput("bad security limit")
        if action not in SECURITY_ACTIONS:
            raise InvalidInput("bad security action")
        if not isinstance(static, list):
            raise InvalidInput("bad security static")
        items = []
        for item in static:
            if (
                not isinstance(item, dict)
                or frozenset(item) != SECURITY_STATIC_KEYS
            ):
                raise InvalidInput("bad security static entry")
            mac = item["mac"]
            vlan = item["vlan"]
            if not valid_mac(mac):
                raise InvalidInput("bad security static mac")
            if not _valid_vlan_id(vlan):
                raise InvalidInput("bad security static vlan")
            if (vlan, mac) in statics:
                raise InvalidInput("security static must be globally distinct")
            statics.add((vlan, mac))
            items.append({"mac": mac, "vlan": vlan})
        parsed.append(
            {
                "port": port,
                "limit": limit,
                "action": action,
                "static": items,
            }
        )
    if seen != names:  # 须互异覆盖全部物理口
        raise InvalidInput("security must cover all ports")
    return (
        bridges, links, delay, bridge, ports, age, storm, lags, mirror, acl,
        qos, parsed,
    )


