        raise InvalidInput("events must be a list")
    for event in events:
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys not in (
            FRAME_DECODE_FRAME_KEYS,
            LINK_WIRE_LINK_EVENT_KEYS,
            LINK_WIRE_ADVANCE_EVENT_KEYS,
        ):  # service 等其他形状一律非法输入
            raise InvalidInput("bad event")
    return validate_link_flow_decode_events(events, fwd_ports)


def _decode_qos_wire_events(events):
    """校验后的事件对：link/advance 原样；frame 附解码九元组。

    与 _decode_link_flow_events 同形（frame-decode 解码，alignment 恒真），
    独立函数以便工作量预演与正式仿真共用同一纯转换。
    """
    raw_frames = [
        (item[1], item[2], item[3]) for item in events if item[0] == "frame"
    ]
    decoded_frames = _decode_raw_frames(raw_frames)
    decoded = []
    frame_index = 0
    for item in events:
        if item[0] == "frame":
            decoded.append(
                ("frame", item[1], item[2], item[3],
                 decoded_frames[frame_index])
            )
            frame_index += 1
        else:
            decoded.append(item)
    return decoded


def _qos_wire_extract_priority(raw):
    """单层 802.1Q 标签帧取 TCI 高 3 位优先级；未标记帧优先级为 0。"""
    if raw[12:14] == FRAME_DECODE_TAG:
        return (raw[14] << 8 | raw[15]) >> 13
    return 0


def qos_wire(
    fwd_ports, caps, queues, flows, qos, age, max_frame, delay, events,
    work_limit=None, observer=None,
):
    """qos-wire-decode 仿真：四优先级队列在线速链路上确定性发送。

    在 link-flow-decode 线速/协商/半双工/PAUSE 模型上，把每口单一等待
    序列改为四个优先级 FIFO（字节与帧双计），受端口总字节限额与每队列
    字节限额约束；发送器空闲（含 advance 结算产生的空闲点）时按 sp
    （最高非空队列）或 wrr（续用 qos-decode 权重轮次与队列顺序、跳过空
    队列）选取下一副本。发送非抢占，链路降级/冲突/PAUSE 语义沿用
    link-flow-decode。work_limit 非 None 时按计费点累计 W（初值 P），
    首次超过即抛 QosWireWorkLimit；预演与正式仿真共用本函数。
    """
    order = {port["name"]: i for i, port in enumerate(fwd_ports)}
    by_name = {port["name"]: port for port in fwd_ports}
    qos_map = qos["map"]
    cap = qos["cap"]
    sched_mode = qos["mode"]
    weights = qos["weights"]
    drop_mode = qos["drop"]
    weight_total = sum(weights)
    # 每队列字节限额：weighted 丢弃按权重上取整，tail 丢弃即端口总限额
    if drop_mode == "tail":
        quotas = [queues[name] for name in by_name]
    else:
        quotas = {
            name: [
                -(-(queues[name] * weights[q]) // weight_total)
                for q in range(4)
            ]
            for name in by_name
        }
    committed = {name: ("down",) for name in by_name}
    pending = {}  # name -> (rate, mode, deadline)
    fdb = {}  # (vlan, mac) -> [port, seen]
    # 每口四队列未完成副本；队头为正在发送副本，其余为等待副本
    waitq = {
        name: [deque(), deque(), deque(), deque()] for name in by_name
    }
    head = {name: None for name in by_name}
    qframes = {name: [0, 0, 0, 0] for name in by_name}
    qbytes = {name: [0, 0, 0, 0] for name in by_name}
    occupied = {name: 0 for name in by_name}  # 四队列（含队头）字节总和
    # 每口持久 WRR 状态 (当前队, 剩余配额)，初始服务 3 队，同 qos-decode
    wrr_state = {name: [3, weights[3]] for name in by_name}
    # PAUSE：pause_until 为发送截止时刻（None 未暂停）；hold_began 为队头
    # 因暂停无法开始的等待区间起点；pause_ns 为累计实际暂停时长
    pause_until = {name: None for name in by_name}
    hold_began = {name: None for name in by_name}
    pause_ns = {name: 0 for name in by_name}
    stats = {
        name: {
            "rx_frames": 0,
            "rx_bytes": 0,
            "tx_frames": 0,
            "tx_bytes": 0,
            "collision_frames": 0,
            "collision_bytes": 0,
            "queue_full_frames": 0,
            "queue_full_bytes": 0,
            "quota_full_frames": 0,
            "quota_full_bytes": 0,
            "link_down_frames": 0,
            "link_down_bytes": 0,
            "pause_frames": 0,
            "pause_unsupported_frames": 0,
            "pause_duration_ns": 0,
        }
        for name in by_name
    }
    results = []
    if observer is not None:
        observer["items"] = []
    work = len(fwd_ports)  # W 初值 P
    if work_limit is not None and work > work_limit:
        raise QosWireWorkLimit()

    def charge(n=1):
        nonlocal work
        work += n
        if work_limit is not None and work > work_limit:
            raise QosWireWorkLimit()

    def is_up(name):
        return name not in pending and committed[name][0] == "up"

    def accrue_hold(name, now):
        # 同 link-flow-decode：按墙钟累计暂停实际生效区间
        began = hold_began[name]
        until = pause_until[name]
        if until is not None and now >= until:
            if began is not None and until > began:
                pause_ns[name] += until - began
            hold_began[name] = None
            pause_until[name] = None
            return
        if began is None or now <= began:
            return
        pause_ns[name] += now - began
        hold_began[name] = now if until is not None else None

    def settle_negotiations(t):
        settled = 0
        for port in fwd_ports:
            name = port["name"]
            if name in pending and pending[name][2] <= t:
                rate, mode, _ = pending.pop(name)
                committed[name] = ("up", rate, mode)
                settled += 1
        return settled

    def pick_waiting(name, now):
        """发送器空闲时选择下一副本并置为队头；无等待返回 False。

        sp：取编号最高的非空队列；wrr：续用持久 (q, rem)，跳过空队列，
        每发一帧 rem 减 1，rem 用尽或当前队变空时推进（队列顺序
        3→2→1→0）并重置配额。
        """
        if sched_mode == "sp":
            q = next((q for q in (3, 2, 1, 0) if waitq[name][q]), None)
            if q is None:
                return False
            copy = waitq[name][q].popleft()
            qframes[name][q] -= 1
            qbytes[name][q] -= copy["bytes"]
        else:
            q, rem = wrr_state[name]
            if not any(qframes[name]):
                return False
            while not waitq[name][q]:  # 跳过空队列并重置其配额
                q = (q - 1) % 4
                rem = weights[q]
            copy = waitq[name][q].popleft()
            qframes[name][q] -= 1
            qbytes[name][q] -= copy["bytes"]
            rem -= 1
            if rem == 0 or not waitq[name][q]:
                q = (q - 1) % 4
                rem = weights[q]
            wrr_state[name] = [q, rem]
        copy["queue"] = q
        head[name] = copy
        start = max(now, copy["ready"])
        until = pause_until[name]
        if until is not None and start < until:
            start = until
        copy["start"] = start
        copy["end"] = start + copy["duration"]
        # 仅当暂停超过自然可发时刻时存在实际等待区间
        hold_began[name] = start if (
            pause_until[name] is not None and start >= pause_until[name]
            and start > now
        ) or (
            pause_until[name] is not None and start == pause_until[name]
            and start > max(now, copy["ready"])
        ) else (hold_began[name] if False else None)
        return True

    def settle_transmissions(t):
        # 结算结束时刻 <= t 的发送：全局按 (end, 口配置序)；一口队头弹出
        # 后发送器空闲，立即选取下一副本（其开始时刻取 max(t, ready)）。
        while True:
            best = None  # (end, port_index, name)
            for name in by_name:
                copy = head[name]
                if copy is not None and copy["end"] <= t:
                    cand = (copy["end"], order[name], name)
                    if best is None or cand < best:
                        best = cand
            if best is None:
                return
            name = best[2]
            copy = head[name]
            head[name] = None
            occupied[name] -= copy["bytes"]
            stats[name]["tx_frames"] += 1
            stats[name]["tx_bytes"] += copy["bytes"]
            results.append(
                {"t": copy["end"], "port": name,
                 "start": copy["start"], "bytes": copy["bytes"],
                 "queue": copy["queue"]}
            )
            charge()
            # 队头完成即空闲：选取下一副本（空闲点发生在 end=copy.end）
            pick_waiting(name, copy["end"])

    def settle(t):
        negotiated = settle_negotiations(t)
        settle_transmissions(t)
        for name in by_name:
            accrue_hold(name, t)
        return negotiated

    def apply_link(t, port, admin, peer, rates, modes):
        if not admin or not peer:
            target = ("down",)
        else:
            local_rates, local_modes = caps[port]
            common_rates = [r for r in local_rates if r in rates]
            common_modes = [m for m in local_modes if m in modes]
            if not common_rates or not common_modes:
                target = ("bad",)
            else:
                target = (
                    "up",
                    max(common_rates),
                    "full" if "full" in common_modes else "half",
                )
        before_up = port not in pending and committed[port][0] == "up"
        current = pending.get(port)
        effective = (
            ("up", current[0], current[1])
            if current is not None
            else committed[port]
        )
        if target == effective:
            applied = False
        elif target[0] == "up":
            pending[port] = (target[1], target[2], t + delay)
            applied = True
        else:
            pending.pop(port, None)
            committed[port] = target
            applied = True
        current = pending.get(port)
        if current is not None:
            state, rate, mode = "wait", None, None
            now_up = False
        else:
            now = committed[port]
            if now[0] == "up":
                state, rate, mode = "up", now[1], now[2]
                now_up = True
            else:
                state, rate, mode = now[0], None, None
                now_up = False
        left_up = before_up and not now_up
        if left_up:
            # 离开 up：先结算本时刻前到期项；清 FDB 与暂停；队头及四队列
            # 全部等待副本按入队序以 link_down 丢弃
            for key in [k for k, (p, _) in fdb.items() if p == port]:
                del fdb[key]
            pause_until[port] = None
            hold_began[port] = None
            order_names = (head[port],)
            head[port] = None
            dropped = []
            if order_names[0] is not None:
                dropped.append(order_names[0])
            for q in range(4):
                dq = waitq[port][q]
                while dq:
                    dropped.append(dq.popleft())
            for copy in dropped:
                q = copy["queue"]
                occupied[port] -= copy["bytes"]
                if copy is not order_names[0]:
                    qframes[port][q] -= 1
                    qbytes[port][q] -= copy["bytes"]
                stats[port]["link_down_frames"] += 1
                stats[port]["link_down_bytes"] += copy["bytes"]
                results.append(
                    {
                        "t": t,
                        "port": port,
                        "start": copy["start"],
                        "bytes": copy["bytes"],
                        "queue": q,
                        "reason": "link_down",
                    }
                )
                charge()
        results.append(
            {"t": t, "port": port, "state": state, "rate": rate, "mode": mode}
        )
        charge()
        return state, rate, mode, applied

    def reschedule(port, ct):
        # 碰撞后：队头已移除，等待副本（四队列内保序、跨队列顺序无关）从
        # 碰撞时刻按各自将被选中的串行时刻重排不可得，故等待副本的 ready
        # 锚点统一取碰撞时刻（其实际开始仍由空闲点选取时串行决定）
        for q in range(4):
            for copy in waitq[port][q]:
                if copy["ready"] < ct:
                    copy["ready"] = ct
                charge()

    def repause(port, t, until):
        """PAUSE 到达：队头（已开始）不动；等待副本整体重锚。

        锚点 = max(当前时钟/队头结束时刻, 新截止时刻)；零值锚点不含截止
        时刻。仅实际后移计费，跨队列顺序不变（各副本保持所属 FIFO）。
        返回（队头结束时刻或 t）。
        """
        inflight = head[port]
        in_flight = inflight if inflight is not None and (
            inflight["start"] <= t
        ) else None
        base = in_flight["end"] if in_flight is not None else t
        anchor = base if until is None else max(base, until)
        for q in range(4):
            for copy in waitq[port][q]:
                if anchor > copy["ready"]:
                    charge()
                copy["ready"] = max(copy["ready"], anchor)
        return base

    indexed = _link_wire_indexed(fwd_ports, events)

    def note_frame(begin):
        if observer is not None:
            observer["items"].append(
                {
                    "kind": "frame",
                    "t": t,
                    "applied": True,
                    "output": list(results[begin:]),
                }
            )

    for _, item in indexed:
        t = item[1]
        begin = len(results)
        negotiated = settle(t)
        charge()  # 每个输入事件计 1
        kind = item[0]
        if kind == "advance":
            applied = negotiated > 0 or len(results) > begin
            if observer is not None:
                observer["items"].append(
                    {
                        "kind": "advance",
                        "t": t,
                        "applied": applied,
                        "output": list(results[begin:]),
                    }
                )
            continue
        if kind == "link":
            _, t, port, admin, peer, rates, modes = item
            _, _, _, applied = apply_link(t, port, admin, peer, rates, modes)
            if observer is not None:
                observer["items"].append(
                    {
                        "kind": "link",
                        "t": t,
                        "applied": applied,
                        "output": list(results[begin:]),
                    }
                )
            continue
        (
            _,
            t,
            port_name,
            raw,
            (_, _, src, dst, tag, length, fcs, alignment),
        ) = item
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        ingress = by_name[port_name]
        inbound_wire = length + LINK_WIRE_OVERHEAD
        if length < FRAME_CHECK_RUNT_LENGTH:
            cls = "runt"
        elif length > max_frame:
            cls = "giant"
        elif not alignment:
            cls = "alignment"
        elif not fcs:
            cls = "bad_fcs"
        else:
            cls = "good"
        is_pause_shape = (
            cls == "good"
            and tag is None
            and dst == LINK_FLOW_PAUSE_DST
            and len(raw) >= 14
            and (raw[12] << 8 | raw[13]) == LINK_FLOW_PAUSE_ETHERTYPE
        )
        hp = head[port_name]
        colliding = (
            not is_pause_shape
            and hp is not None
            and is_up(port_name)
            and committed[port_name][2] == "half"
            and hp["start"] <= t < hp["end"]
        )
        if colliding:
            # half 口自身发送区间收帧：入站帧与队头均终止、不学习，等待
            # 副本自碰撞时刻重锚
            copy = head[port_name]
            head[port_name] = None
            occupied[port_name] -= copy["bytes"]
            key = (copy["fvlan"], copy["fsrc"])
            if fdb.get(key) == [copy["fing"], copy["fseen"]]:
                del fdb[key]
            stats[port_name]["collision_frames"] += 2
            stats[port_name]["collision_bytes"] += (
                inbound_wire + copy["bytes"]
            )
            results.append(
                {
                    "t": t,
                    "port": port_name,
                    "start": copy["start"],
                    "bytes": copy["bytes"],
                    "queue": copy["queue"],
                    "inbound": inbound_wire,
                    "reason": "collision",
                }
            )
            charge()
            reschedule(port_name, t)
            # 碰撞点发送器空闲：立即选取下一副本，锚点为碰撞时刻 t
            pick_waiting(port_name, t)
            note_frame(begin)
            continue
        stats[port_name]["rx_frames"] += 1
        stats[port_name]["rx_bytes"] += inbound_wire
        if cls != "good":
            results.append(
                {"t": t, "class": cls, "action": "drop", "ports": []}
            )
            charge()
            note_frame(begin)
            continue
        if is_pause_shape:
            opcode = (raw[14] << 8) | raw[15] if len(raw) >= 16 else None
            reserved_ok = (
                length == FRAME_CHECK_RUNT_LENGTH
                and len(raw) >= 60
                and not any(raw[18:length - 4])
            )
            if (
                length != FRAME_CHECK_RUNT_LENGTH
                or opcode != LINK_FLOW_PAUSE_OPCODE
                or not reserved_ok
            ):
                results.append(
                    {"t": t, "port": port_name,
                     "action": "malformed_pause"}
                )
                charge()
                note_frame(begin)
                continue
            stats[port_name]["pause_frames"] += 1
            quanta = (raw[16] << 8) | raw[17]
            if not (
                is_up(port_name)
                and committed[port_name][2] == "full"
                and flows[port_name]
            ):
                stats[port_name]["pause_unsupported_frames"] += 1
                results.append(
                    {"t": t, "port": port_name,
                     "action": "pause_unsupported"}
                )
                charge()
                note_frame(begin)
                continue
            if quanta == 0:
                pause_until[port_name] = None
                hold_began[port_name] = None
                repause(port_name, t, None)
                results.append(
                    {"t": t, "port": port_name, "action": "pause",
                     "quanta": 0, "until": None}
                )
                charge()
                note_frame(begin)
                continue
            rate = committed[port_name][1]
            until = t + (
                quanta * LINK_FLOW_PAUSE_QUANTA_TICKS + rate - 1
            ) // rate
            pause_until[port_name] = until
            base = repause(port_name, t, until)
            hold_began[port_name] = base if until > base else None
            results.append(
                {"t": t, "port": port_name, "action": "pause",
                 "quanta": quanta, "until": until}
            )
            charge()
            note_frame(begin)
            continue
        if tag is None:
            vlan = ingress["pvid"]
            rejected = False
            tagged_ingress = False
        else:
            vlan = tag
            tagged_ingress = True
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if rejected:
            results.append(
                {"t": t, "class": cls, "action": "drop", "ports": []}
            )
            charge()
            note_frame(begin)
            continue
        egress = []
        action = "drop"
        if is_up(port_name):
            fdb[(vlan, src)] = [port_name, t]
            hit = None if dst == BROADCAST_MAC else fdb.get((vlan, dst))
            if hit is not None and hit[0] != port_name:
                target_name = hit[0]
                if (
                    is_up(target_name)
                    and vlan in by_name[target_name]["allowed"]
                ):
                    egress = [target_name]
                    action = "unicast"
            elif hit is None:
                egress = [
                    port["name"]
                    for port in fwd_ports
                    if vlan in port["allowed"]
                    and is_up(port["name"])
                    and port["name"] != port_name
                ]
                if egress:
                    action = "flood"
        out_ports = []
        copies = []
        for name in egress:
            out_vlan = None if vlan in by_name[name]["untagged"] else vlan
            out_ports.append({"name": name, "vlan": out_vlan})
            frame_len = length + (
                4 if not tagged_ingress and out_vlan is not None else
                -4 if tagged_ingress and out_vlan is None else 0
            )
            wire_bytes = frame_len + LINK_WIRE_OVERHEAD
            copies.append((name, out_vlan, wire_bytes))
        results.append(
            {"t": t, "class": cls, "action": action, "ports": out_ports}
        )
        charge()
        # 出口副本按最终 802.1Q 优先级入对应队列
        qi = qos_map[_qos_wire_extract_priority(raw)]
        for name, out_vlan, wire_bytes in copies:
            egr_rate = committed[name][1]
            duration = (wire_bytes * 8000 + egr_rate - 1) // egr_rate
            limit_total = queues[name]
            limit_queue = (
                limit_total if drop_mode == "tail" else quotas[name][qi]
            )
            if occupied[name] + wire_bytes > limit_total:
                stats[name]["queue_full_frames"] += 1
                stats[name]["queue_full_bytes"] += wire_bytes
                results.append(
                    {
                        "t": t,
                        "port": name,
                        "vlan": out_vlan,
                        "bytes": wire_bytes,
                        "queue": qi,
                        "reason": "queue_full",
                    }
                )
                charge()
                continue  # 端口总字节限额：拒绝只影响该出口
            if qbytes[name][qi] + wire_bytes > limit_queue:
                stats[name]["quota_full_frames"] += 1
                stats[name]["quota_full_bytes"] += wire_bytes
                results.append(
                    {
                        "t": t,
                        "port": name,
                        "vlan": out_vlan,
                        "bytes": wire_bytes,
                        "queue": qi,
                        "reason": "quota_full",
                    }
                )
                charge()
                continue  # 本队列字节限额：拒绝只影响该出口
            # 新副本接本队列队尾；发送器忙时就绪时刻不早于队头/同队尾，
            # 空闲时立即参与选取。ready 为最早可开始时刻，PAUSE 在选取点
            # 再夹截止时刻。
            hp = head[name]
            if hp is None:
                ready = t
            else:
                tail_same = (
                    waitq[name][qi][-1]["ready"] + waitq[name][qi][-1]
                    ["duration"]
                    if waitq[name][qi] else None
                )
                ready = max(t, hp["end"])
                if tail_same is not None:
                    ready = max(ready, tail_same)
            until = pause_until[name]
            if until is not None and ready < until:
                ready = until
            copy = {
                "egress": name,
                "vlan": out_vlan,
                "bytes": wire_bytes,
                "duration": duration,
                "ready": ready,
                "start": 0,
                "end": 0,
                "queue": qi,
                "fvlan": vlan,
                "fsrc": src,
                "fing": port_name,
                "fseen": t,
            }
            waitq[name][qi].append(copy)
            qframes[name][qi] += 1
            qbytes[name][qi] += wire_bytes
            occupied[name] += wire_bytes
            results.append(
                {"t": t, "port": name, "vlan": out_vlan,
                 "bytes": wire_bytes, "queue": qi}
            )
            charge()
            # 发送器空闲：立即选取下一副本（本副本或更高优先级既有副本）
            if head[name] is None:
                pick_waiting(name, t)
        note_frame(begin)
    # 末事件后不自动排空
    port_docs = []
    for name in by_name:
        queue_docs = []
        for q in range(4):
            queue_docs.append(
                {
                    "frames": qframes[name][q],
                    "bytes": qbytes[name][q],
                    "sent": stats[name]["tx_frames_queue"][q]
                    if False else None,
                }
            )
        # 每队列发送与丢弃计数
        port_docs.append(name)
    return {
        "results": results,
        "ports": [
            {
                "name": name,
                "queues": [
                    {
                        "frames": qframes[name][q],
                        "bytes": qbytes[name][q],
                        "sent": tx_queue[name][q],
                        "dropped": drop_queue[name][q],
                    }
                    for q in range(4)
                ],
                "rx_frames": stats[name]["rx_frames"],
                "rx_bytes": stats[name]["rx_bytes"],
                "tx_frames": stats[name]["tx_frames"],
                "tx_bytes": stats[name]["tx_bytes"],
                "collision_frames": stats[name]["collision_frames"],
                "collision_bytes": stats[name]["collision_bytes"],
                "queue_full_frames": stats[name]["queue_full_frames"],
                "queue_full_bytes": stats[name]["queue_full_bytes"],
                "quota_full_frames": stats[name]["quota_full_frames"],
                "quota_full_bytes": stats[name]["quota_full_bytes"],
                "link_down_frames": stats[name]["link_down_frames"],
                "link_down_bytes": stats[name]["link_down_bytes"],
                "pause_frames": stats[name]["pause_frames"],
                "pause_unsupported_frames":
                    stats[name]["pause_unsupported_frames"],
                "pause_duration_ns": pause_ns[name],
            }
            for name in by_name
        ],
    }


def qos_wire_work(fwd_ports, caps, queues, flows, qos, age, max_frame, delay,
                  events, limit):
    """qos-wire-decode 工作量预演：独立状态跑同一仿真，无副作用、不产出。

    与 qos_wire 同一计费公式（W 初值 P，每输入事件、每条 results 记录、
    碰撞/PAUSE 后每个实际受影响副本各计 1），等于上限合法，首次超过即
    抛 QosWireWorkLimit。
    """
    qos_wire(
        fwd_ports, caps, queues, flows, qos, age, max_frame, delay, events,
        work_limit=limit,
    )


STP_CHECK_CONFIG_KEYS = frozenset(
    ("bridges", "links", "delay", "bridge", "ports", "age", "max_frame")
)

toolUseResult.newString:
# ---------------------------------------------------------------------------
# qos-wire-decode：CONFIG 复用 link-flow-decode 的端口模式、协商、总字节
# 缓存（queue_bytes）、流控（flow_control）、老化与最大帧，顶层再加 qos
# （map/cap/mode/weights/drop，形状同 qos-decode）。事件仅接受原始帧、
# link、advance（service 一律非法）。帧合法性、VLAN 归属与转发判定沿用
# link-flow-decode；各出口副本按最终 802.1Q priority 经 map 入四个优先级
# 队列，同时受本队列字节限额与端口总字节限额约束，拒绝只影响该出口。
# 发送器空闲（或 advance 结算出现空闲点）时按 sp/wrr 选取下一副本；发送
# 不可抢占，时长按协商速率、帧长与 20 字节线缆开销向上取整。链路降级、
# 半双工冲突及 PAUSE 对在发帧与等待队列的影响沿用 link-flow-decode；同一
# 时刻先结算到期项，末事件后不自动排空。
# ---------------------------------------------------------------------------

QOS_WIRE_CONFIG_KEYS = LINK_WIRE_CONFIG_KEYS | frozenset(("qos",))


def validate_qos_wire_config(config):
    """qos-wire-decode 配置：link-flow-decode 五键加 qos 子文档。"""
    if (
        not isinstance(config, dict)
        or frozenset(config) != QOS_WIRE_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    # ports/age/max_frame/delay（含 rates/modes/queue_bytes/flow_control）
    # 全量校验同 link-flow-decode
    fwd_ports, caps, queues, flows, age, max_frame, delay = (
        validate_link_flow_config(
            {key: config[key] for key in LINK_WIRE_CONFIG_KEYS}
        )
    )
    qos_doc = config["qos"]
    if not isinstance(qos_doc, dict) or frozenset(qos_doc) != QOS_KEYS:
        raise InvalidInput("bad qos")
    mapping = qos_doc["map"]
    cap = qos_doc["cap"]
    mode = qos_doc["mode"]
    weights = qos_doc["weights"]
    drop = qos_doc["drop"]
    if (
        not isinstance(mapping, list)
        or len(mapping) != 8
        or not all(_is_int(q) and 0 <= q <= 3 for q in mapping)
    ):
        raise InvalidInput("bad qos map")
    if not _is_int(cap) or cap <= 0:
        raise InvalidInput("bad qos cap")
    if mode not in QOS_SCHED_MODES:
        raise InvalidInput("bad qos mode")
    if (
        not isinstance(weights, list)
        or len(weights) != 4
        or not all(_is_int(w) and w > 0 for w in weights)
    ):
        raise InvalidInput("bad qos weights")
    if drop not in QOS_DROP_MODES:
        raise InvalidInput("bad qos drop")
    qos = {
        "map": list(mapping),
        "cap": cap,
        "mode": mode,
        "weights": list(weights),
        "drop": drop,
    }
    return fwd_ports, caps, queues, flows, qos, age, max_frame, delay


def validate_qos_wire_events(events, fwd_ports):
    """qos-wire-decode 事件：link/advance/{t,port,data}，service 非法。

    全量校验口径同 link-flow-decode（PAUSE 合法性是运行期结果而非输入
    错误），仅在事件形状层面拒绝 service 及其余未知形状。
    """
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    for event in events:
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys not in (
            FRAME_DECODE_FRAME_KEYS,
            LINK_WIRE_LINK_EVENT_KEYS,
            LINK_WIRE_ADVANCE_EVENT_KEYS,
        ):  # service 等其他形状一律非法输入
            raise InvalidInput("bad event")
    return validate_link_flow_decode_events(events, fwd_ports)


def _decode_qos_wire_events(events):
    """校验后的事件对：link/advance 原样；frame 附解码九元组。

    与 _decode_link_flow_events 同形（frame-decode 解码，alignment 恒真），
    独立函数以便工作量预演与正式仿真共用同一纯转换。
    """
    raw_frames = [
        (item[1], item[2], item[3]) for item in events if item[0] == "frame"
    ]
    decoded_frames = _decode_raw_frames(raw_frames)
    decoded = []
    frame_index = 0
    for item in events:
        if item[0] == "frame":
            decoded.append(
                ("frame", item[1], item[2], item[3],
                 decoded_frames[frame_index])
            )
            frame_index += 1
        else:
            decoded.append(item)
    return decoded


def _qos_wire_extract_priority(raw):
    """单层 802.1Q 标签帧取 TCI 高 3 位优先级；未标记帧优先级为 0。"""
    if raw[12:14] == FRAME_DECODE_TAG:
        return (raw[14] << 8 | raw[15]) >> 13
    return 0


def qos_wire(
    fwd_ports, caps, queues, flows, qos, age, max_frame, delay, events,
    work_limit=None, observer=None,
):
    """qos-wire-decode 仿真：四优先级队列在线速链路上确定性发送。

    在 link-flow-decode 线速/协商/半双工/PAUSE 模型上，把每口单一等待
    序列改为四个优先级 FIFO（字节与帧双计），受端口总字节限额与每队列
    字节限额约束；发送器空闲（含 advance 结算产生的空闲点）时按 sp
    （最高非空队列）或 wrr（续用 qos-decode 权重轮次与队列顺序、跳过空
    队列）选取下一副本。发送非抢占，链路降级/冲突/PAUSE 语义沿用
    link-flow-decode。work_limit 非 None 时按计费点累计 W（初值 P），
    首次超过即抛 QosWireWorkLimit；预演与正式仿真共用本函数。
    """
    order = {port["name"]: i for i, port in enumerate(fwd_ports)}
    by_name = {port["name"]: port for port in fwd_ports}
    qos_map = qos["map"]
    cap = qos["cap"]
    sched_mode = qos["mode"]
    weights = qos["weights"]
    drop_mode = qos["drop"]
    weight_total = sum(weights)
    # 每队列字节限额：weighted 丢弃按权重上取整，tail 丢弃即端口总限额
    if drop_mode == "tail":
        quotas = [queues[name] for name in by_name]
    else:
        quotas = {
            name: [
                -(-(queues[name] * weights[q]) // weight_total)
                for q in range(4)
            ]
            for name in by_name
        }
    committed = {name: ("down",) for name in by_name}
    pending = {}  # name -> (rate, mode, deadline)
    fdb = {}  # (vlan, mac) -> [port, seen]
    # 每口四队列未完成副本；队头为正在发送副本，其余为等待副本
    waitq = {
        name: [deque(), deque(), deque(), deque()] for name in by_name
    }
    head = {name: None for name in by_name}
    qframes = {name: [0, 0, 0, 0] for name in by_name}
    qbytes = {name: [0, 0, 0, 0] for name in by_name}
    occupied = {name: 0 for name in by_name}  # 四队列（含队头）字节总和
    # 每口持久 WRR 状态 (当前队, 剩余配额)，初始服务 3 队，同 qos-decode
    wrr_state = {name: [3, weights[3]] for name in by_name}
    # PAUSE：pause_until 为发送截止时刻（None 未暂停）；hold_began 为队头
    # 因暂停无法开始的等待区间起点；pause_ns 为累计实际暂停时长
    pause_until = {name: None for name in by_name}
    hold_began = {name: None for name in by_name}
    pause_ns = {name: 0 for name in by_name}
    stats = {
        name: {
            "rx_frames": 0,
            "rx_bytes": 0,
            "tx_frames": 0,
            "tx_bytes": 0,
            "collision_frames": 0,
            "collision_bytes": 0,
            "queue_full_frames": 0,
            "queue_full_bytes": 0,
            "quota_full_frames": 0,
            "quota_full_bytes": 0,
            "link_down_frames": 0,
            "link_down_bytes": 0,
            "pause_frames": 0,
            "pause_unsupported_frames": 0,
            "pause_duration_ns": 0,
        }
        for name in by_name
    }
    results = []
    if observer is not None:
        observer["items"] = []
    work = len(fwd_ports)  # W 初值 P
    if work_limit is not None and work > work_limit:
        raise QosWireWorkLimit()

    def charge(n=1):
        nonlocal work
        work += n
        if work_limit is not None and work > work_limit:
            raise QosWireWorkLimit()

    def is_up(name):
        return name not in pending and committed[name][0] == "up"

    def accrue_hold(name, now):
        # 同 link-flow-decode：按墙钟累计暂停实际生效区间
        began = hold_began[name]
        until = pause_until[name]
        if until is not None and now >= until:
            if began is not None and until > began:
                pause_ns[name] += until - began
            hold_began[name] = None
            pause_until[name] = None
            return
        if began is None or now <= began:
            return
        pause_ns[name] += now - began
        hold_began[name] = now if until is not None else None

    def settle_negotiations(t):
        settled = 0
        for port in fwd_ports:
            name = port["name"]
            if name in pending and pending[name][2] <= t:
                rate, mode, _ = pending.pop(name)
                committed[name] = ("up", rate, mode)
                settled += 1
        return settled

    def pick_waiting(name, now):
        """发送器空闲时选择下一副本并置为队头；无等待返回 False。

        sp：取编号最高的非空队列；wrr：续用持久 (q, rem)，跳过空队列，
        每发一帧 rem 减 1，rem 用尽或当前队变空时推进（队列顺序
        3→2→1→0）并重置配额。
        """
        if sched_mode == "sp":
            q = next((q for q in (3, 2, 1, 0) if waitq[name][q]), None)
            if q is None:
                return False
            copy = waitq[name][q].popleft()
            qframes[name][q] -= 1
            qbytes[name][q] -= copy["bytes"]
        else:
            q, rem = wrr_state[name]
            if not any(qframes[name]):
                return False
            while not waitq[name][q]:  # 跳过空队列并重置其配额
                q = (q - 1) % 4
                rem = weights[q]
            copy = waitq[name][q].popleft()
            qframes[name][q] -= 1
            qbytes[name][q] -= copy["bytes"]
            rem -= 1
            if rem == 0 or not waitq[name][q]:
                q = (q - 1) % 4
                rem = weights[q]
            wrr_state[name] = [q, rem]
        copy["queue"] = q
        head[name] = copy
        start = max(now, copy["ready"])
        until = pause_until[name]
        if until is not None and start < until:
            start = until
        copy["start"] = start
        copy["end"] = start + copy["duration"]
        # 仅当暂停超过自然可发时刻时存在实际等待区间
        hold_began[name] = start if (
            pause_until[name] is not None and start >= pause_until[name]
            and start > now
        ) or (
            pause_until[name] is not None and start == pause_until[name]
            and start > max(now, copy["ready"])
        ) else (hold_began[name] if False else None)
        return True

    def settle_transmissions(t):
        # 结算结束时刻 <= t 的发送：全局按 (end, 口配置序)；一口队头弹出
        # 后发送器空闲，立即选取下一副本（其开始时刻取 max(t, ready)）。
        while True:
            best = None  # (end, port_index, name)
            for name in by_name:
                copy = head[name]
                if copy is not None and copy["end"] <= t:
                    cand = (copy["end"], order[name], name)
                    if best is None or cand < best:
                        best = cand
            if best is None:
                return
            name = best[2]
            copy = head[name]
            head[name] = None
            occupied[name] -= copy["bytes"]
            stats[name]["tx_frames"] += 1
            stats[name]["tx_bytes"] += copy["bytes"]
            results.append(
                {"t": copy["end"], "port": name,
                 "start": copy["start"], "bytes": copy["bytes"],
                 "queue": copy["queue"]}
            )
            charge()
            # 队头完成即空闲：选取下一副本（空闲点发生在 end=copy.end）
            pick_waiting(name, copy["end"])

    def settle(t):
        negotiated = settle_negotiations(t)
        settle_transmissions(t)
        for name in by_name:
            accrue_hold(name, t)
        return negotiated

    def apply_link(t, port, admin, peer, rates, modes):
        if not admin or not peer:
            target = ("down",)
        else:
            local_rates, local_modes = caps[port]
            common_rates = [r for r in local_rates if r in rates]
            common_modes = [m for m in local_modes if m in modes]
            if not common_rates or not common_modes:
                target = ("bad",)
            else:
                target = (
                    "up",
                    max(common_rates),
                    "full" if "full" in common_modes else "half",
                )
        before_up = port not in pending and committed[port][0] == "up"
        current = pending.get(port)
        effective = (
            ("up", current[0], current[1])
            if current is not None
            else committed[port]
        )
        if target == effective:
            applied = False
        elif target[0] == "up":
            pending[port] = (target[1], target[2], t + delay)
            applied = True
        else:
            pending.pop(port, None)
            committed[port] = target
            applied = True
        current = pending.get(port)
        if current is not None:
            state, rate, mode = "wait", None, None
            now_up = False
        else:
            now = committed[port]
            if now[0] == "up":
                state, rate, mode = "up", now[1], now[2]
                now_up = True
            else:
                state, rate, mode = now[0], None, None
                now_up = False
        left_up = before_up and not now_up
        if left_up:
            # 离开 up：先结算本时刻前到期项；清 FDB 与暂停；队头及四队列
            # 全部等待副本按入队序以 link_down 丢弃
            for key in [k for k, (p, _) in fdb.items() if p == port]:
                del fdb[key]
            pause_until[port] = None
            hold_began[port] = None
            order_names = (head[port],)
            head[port] = None
            dropped = []
            if order_names[0] is not None:
                dropped.append(order_names[0])
            for q in range(4):
                dq = waitq[port][q]
                while dq:
                    dropped.append(dq.popleft())
            for copy in dropped:
                q = copy["queue"]
                occupied[port] -= copy["bytes"]
                if copy is not order_names[0]:
                    qframes[port][q] -= 1
                    qbytes[port][q] -= copy["bytes"]
                stats[port]["link_down_frames"] += 1
                stats[port]["link_down_bytes"] += copy["bytes"]
                results.append(
                    {
                        "t": t,
                        "port": port,
                        "start": copy["start"],
                        "bytes": copy["bytes"],
                        "queue": q,
                        "reason": "link_down",
                    }
                )
                charge()
        results.append(
            {"t": t, "port": port, "state": state, "rate": rate, "mode": mode}
        )
        charge()
        return state, rate, mode, applied

    def reschedule(port, ct):
        # 碰撞后：队头已移除，等待副本（四队列内保序、跨队列顺序无关）从
        # 碰撞时刻按各自将被选中的串行时刻重排不可得，故等待副本的 ready
        # 锚点统一取碰撞时刻（其实际开始仍由空闲点选取时串行决定）
        for q in range(4):
            for copy in waitq[port][q]:
                if copy["ready"] < ct:
                    copy["ready"] = ct
                charge()

    def repause(port, t, until):
        """PAUSE 到达：队头（已开始）不动；等待副本整体重锚。

        锚点 = max(当前时钟/队头结束时刻, 新截止时刻)；零值锚点不含截止
        时刻。仅实际后移计费，跨队列顺序不变（各副本保持所属 FIFO）。
        返回（队头结束时刻或 t）。
        """
        inflight = head[port]
        in_flight = inflight if inflight is not None and (
            inflight["start"] <= t
        ) else None
        base = in_flight["end"] if in_flight is not None else t
        anchor = base if until is None else max(base, until)
        for q in range(4):
            for copy in waitq[port][q]:
                if anchor > copy["ready"]:
                    charge()
                copy["ready"] = max(copy["ready"], anchor)
        return base

    indexed = _link_wire_indexed(fwd_ports, events)

    def note_frame(begin):
        if observer is not None:
            observer["items"].append(
                {
                    "kind": "frame",
                    "t": t,
                    "applied": True,
                    "output": list(results[begin:]),
                }
            )

    for _, item in indexed:
        t = item[1]
        begin = len(results)
        negotiated = settle(t)
        charge()  # 每个输入事件计 1
        kind = item[0]
        if kind == "advance":
            applied = negotiated > 0 or len(results) > begin
            if observer is not None:
                observer["items"].append(
                    {
                        "kind": "advance",
                        "t": t,
                        "applied": applied,
                        "output": list(results[begin:]),
                    }
                )
            continue
        if kind == "link":
            _, t, port, admin, peer, rates, modes = item
            _, _, _, applied = apply_link(t, port, admin, peer, rates, modes)
            if observer is not None:
                observer["items"].append(
                    {
                        "kind": "link",
                        "t": t,
                        "applied": applied,
                        "output": list(results[begin:]),
                    }
                )
            continue
        (
            _,
            t,
            port_name,
            raw,
            (_, _, src, dst, tag, length, fcs, alignment),
        ) = item
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        ingress = by_name[port_name]
        inbound_wire = length + LINK_WIRE_OVERHEAD
        if length < FRAME_CHECK_RUNT_LENGTH:
            cls = "runt"
        elif length > max_frame:
            cls = "giant"
        elif not alignment:
            cls = "alignment"
        elif not fcs:
            cls = "bad_fcs"
        else:
            cls = "good"
        is_pause_shape = (
            cls == "good"
            and tag is None
            and dst == LINK_FLOW_PAUSE_DST
            and len(raw) >= 14
            and (raw[12] << 8 | raw[13]) == LINK_FLOW_PAUSE_ETHERTYPE
        )
        hp = head[port_name]
        colliding = (
            not is_pause_shape
            and hp is not None
            and is_up(port_name)
            and committed[port_name][2] == "half"
            and hp["start"] <= t < hp["end"]
        )
        if colliding:
            # half 口自身发送区间收帧：入站帧与队头均终止、不学习，等待
            # 副本自碰撞时刻重锚
            copy = head[port_name]
            head[port_name] = None
            occupied[port_name] -= copy["bytes"]
            key = (copy["fvlan"], copy["fsrc"])
            if fdb.get(key) == [copy["fing"], copy["fseen"]]:
                del fdb[key]
            stats[port_name]["collision_frames"] += 2
            stats[port_name]["collision_bytes"] += (
                inbound_wire + copy["bytes"]
            )
            results.append(
                {
                    "t": t,
                    "port": port_name,
                    "start": copy["start"],
