def config(q=None, ports=None, drop="tail", mode="sp", weights=None, cap=100000):
    if q is None:
        q = {"map": [0,0,0,0,0,0,0,0], "cap": cap, "mode": mode,
             "weights": weights or [1,1,1,1], "drop": drop}
    return {"ports": ports or [port("p1"), port("p2")], "age": 100,
            "max_frame": 1518, "delay": 10, "qos": q}

def link(t, p):
    return {"t": t, "port": p, "admin": True, "peer": True,
            "rates": [1000], "modes": ["full"]}

def advance(t):
    return {"t": t, "advance": True}

def mac(m):
    return bytes(int(x,16) for x in m.split(":"))

def raw(t, p, dst="ff:ff:ff:ff:ff:ff", src="00:00:00:00:00:01",
        vlan=None, prio=0, payload_len=46):
    if vlan is None:
        head = mac(dst)+mac(src)+(0x0800).to_bytes(2,"big")
    else:
        tci = (prio<<13)|vlan
        head = mac(dst)+mac(src)+b"\x81\x00"+tci.to_bytes(2,"big")+(0x0800).to_bytes(2,"big")
    body = head + b"\x00"*payload_len
    fcs = (zlib.crc32(body)&0xFFFFFFFF).to_bytes(4,"little")
    return {"t": t, "port": p, "data": (body+fcs).hex()}

def run(cfg, ev, *limits):
    with tempfile.TemporaryDirectory() as d:
        cp = os.path.join(d,"c.json"); ep = os.path.join(d,"e.json")
        open(cp,"w").write(json.dumps(cfg)); open(ep,"w").write(json.dumps(ev))
        r = subprocess.run([sys.executable, SWITCH, "qos-wire-decode", cp, ep,
                            *map(str,limits)], capture_output=True)
    return r

